/* Country-wide navigation preferences. Authorization stays in each original view/API. */
(function(){
const words={
 navigation:['選單排版與名稱設定','Menu layout and names','Diseño y nombres del menú','Bố cục và tên menu'],
 custom_ehs:['EHS管理','EHS Management','Gestión de EHS','Quản lý EHS'],
 items:['機器日常點檢設定','Machine daily inspection settings','Configurar inspección diaria de máquinas','Thiết lập kiểm tra máy hằng ngày'],
 visual:['QR18-03 機器日常點檢表','QR18-03 Machine daily checklist','QR18-03 Inspección diaria de máquinas','QR18-03 Kiểm tra máy hằng ngày'],
 qr03:['QR18-03 每日設備點檢輸入','QR18-03 Daily inspection entry','QR18-03 Ingreso de inspección diaria','QR18-03 Nhập kiểm tra hằng ngày'],
 qr04:['QR18-04 預防保養記錄表','QR18-04 Preventive maintenance record','QR18-04 Registro de mantenimiento preventivo','QR18-04 Hồ sơ bảo dưỡng phòng ngừa'],
 maintenance:['QR18-04 預防保養設備設定','QR18-04 Preventive maintenance equipment settings','QR18-04 Configurar equipos de mantenimiento','QR18-04 Thiết lập thiết bị bảo dưỡng'],
 backfill:['QR18-03 每日設備點檢(補登)','QR18-03 Daily inspection (backfill)','QR18-03 Inspección diaria (registro atrasado)','QR18-03 Kiểm tra hằng ngày (bổ sung)'],
 formExport:['QR18-03 點檢報表匯出 (Excel)','QR18-03 Export inspection reports (Excel)','QR18-03 Exportar informes (Excel)','QR18-03 Xuất báo cáo kiểm tra (Excel)'],
 navHelp:['名稱、順序與顯示設定儲存於目前國家，所有帳號下次載入時套用。各帳號仍只看得到有權限的功能。空白名稱沿用原名稱。','Names, order and visibility are saved for this country and apply on the next load. Account permissions still apply. Blank names use the original.','Los nombres, orden y visibilidad se guardan por país y se aplican al recargar. Se mantienen los permisos. Un nombre vacío usa el original.','Tên, thứ tự và hiển thị được lưu theo quốc gia, áp dụng khi tải lại. Vẫn giữ quyền tài khoản. Tên trống dùng tên gốc.'],
 navName:['顯示名稱','Display name','Nombre mostrado','Tên hiển thị'],navVisible:['顯示','Visible','Visible','Hiển thị'],navGroup:['分類','Group','Grupo','Nhóm'],navUp:['上移','Move up','Subir','Lên'],navDown:['下移','Move down','Bajar','Xuống'],navReset:['恢復原始選單','Restore original menu','Restaurar menú original','Khôi phục menu gốc'],navResetConfirm:['將目前編輯內容恢復原始選單？儲存後才會套用。','Restore the editor to the original menu? Save to apply.','¿Restaurar el editor al menú original? Guarde para aplicar.','Khôi phục menu gốc trong trình sửa? Lưu để áp dụng.'],navConflict:['其他管理員已更新選單。您的編輯仍保留，請重新載入最新設定後再修改。','Another administrator updated the menu. Your edits remain; reload the latest settings before editing again.','Otro administrador actualizó el menú. Sus cambios se conservan; recargue antes de editar otra vez.','Quản trị viên khác đã cập nhật menu. Vẫn giữ nội dung bạn sửa; tải lại trước khi sửa tiếp.'],navReload:['重新載入設定','Reload settings','Recargar ajustes','Tải lại thiết lập'],navDiscard:['尚有未儲存的選單修改，確定離開？','Leave with unsaved menu changes?','¿Salir sin guardar los cambios del menú?','Rời đi khi thay đổi menu chưa lưu?'],navInvalid:['未儲存。請確認名稱不超過 120 字且沒有 < 或 >，並確認網路連線。','Not saved. Use names up to 120 characters without < or > and check your connection.','No guardado. Use hasta 120 caracteres sin < ni > y compruebe la conexión.','Chưa lưu. Tên tối đa 120 ký tự, không có < hoặc >; kiểm tra mạng.'],navAddGroup:['新增分類','Add group','Añadir grupo','Thêm nhóm'],navGroupName:['新分類名稱','New group name','Nombre del grupo nuevo','Tên nhóm mới'],
 duplicatesHint:['相同內容的螺帽成型組表單已合併顯示；設備分配及歷史紀錄仍保留。修改代表表單只影響該表單；需要調整其他設備時可展開重複表單。','Identical nut forming forms are grouped here; assignments and history are retained. Editing affects only the selected form; expand duplicates to edit other equipment.','Aquí se agrupan formularios idénticos de conformado de tuercas; se conservan asignaciones e historial. Editar afecta solo al formulario elegido; muestre duplicados para otros equipos.','Gộp hiển thị mẫu giống nhau của tổ tạo hình đai ốc; giữ phân công và lịch sử. Sửa chỉ áp dụng mẫu đã chọn; mở mẫu trùng để sửa thiết bị khác.'],showDuplicates:['顯示重複表單','Show duplicate forms','Mostrar formularios duplicados','Hiện biểu mẫu trùng'],
 offlineHint:['目前離線。請保留此頁，連線恢復後再儲存；尚未送出的內容不會自動上傳。','You are offline. Keep this page open and save after reconnecting; unsent changes are not uploaded automatically.','Sin conexión. Mantenga esta página abierta y guarde al reconectar; los cambios no se suben automáticamente.','Đang ngoại tuyến. Giữ trang mở và lưu khi có mạng; nội dung chưa gửi không tự tải lên.'],networkProblem:['暫時無法連線，請保留此頁並確認網路後重試儲存。','Connection unavailable. Keep this page open and retry saving after checking the network.','Conexión no disponible. Mantenga esta página abierta y reintente guardar tras revisar la red.','Tạm mất kết nối. Giữ trang mở, kiểm tra mạng rồi thử lưu lại.'],networkBack:['網路已恢復，可繼續儲存。','Connection restored; you can save now.','Conexión restablecida; ya puede guardar.','Đã có mạng; có thể tiếp tục lưu.']
};
for(const[k,v]of Object.entries(words))translations[k]=Object.fromEntries(['zh','en','es','vi'].map((l,n)=>[l,v[n]]));
const sections=['field','custom_ehs','supervisor','backoffice'];
const ehsKeys=['craneDaily','craneMonthly','fireDaily'];
const defaults={field:['board','visual','qr03','qr04','cadre','environment','history','settings'],custom_ehs:ehsKeys,supervisor:['approval','scrap','scrapDetails','cadreManage','craneMonthlyManage','environmentManage','items','maintenance','backfill','assignment','equipmentAdmin','mapping','formExport'],backoffice:['accounts','database','dataExport','adminDailyNormal','cadreBulk','companyCalendar','navigation']};
const keys=Object.values(defaults).flat();
const original=()=>({sections:sections.map(id=>({id,label:{}})),items:Object.entries(defaults).flatMap(([section,ks])=>ks.map(key=>({key,section,visible:true,label:{}})))});
function config(){const c=structuredClone(data.navigationSettings?.config||original());for(const key of keys)if(!c.items.some(x=>x.key===key))c.items.push(original().items.find(x=>x.key===key));if(!c.sections.some(s=>s.id==='custom_ehs')){const fieldIndex=c.sections.findIndex(s=>s.id==='field');c.sections.splice(fieldIndex+1,0,{id:'custom_ehs',label:{}});const moved=ehsKeys.map(key=>c.items.find(i=>i.key===key)).filter(Boolean);c.items=c.items.filter(i=>!ehsKeys.includes(i.key));const afterField=c.items.findLastIndex(i=>i.section==='field')+1;for(const item of moved){item.section='custom_ehs';item.visible=true;}c.items.splice(afterField,0,...moved);}return c;}
function label(v,key){return Object.fromEntries(['zh','en','es','vi'].map(l=>[l,v?.[l]||translations[key]?.[l]||v?.zh||key]));}
let draft=null,dirty=false,saving=false,showDuplicates=false,networkFailed=false;
function draftForCountry(){if(!draft||draft.country!==activeCountry||draft.account!==profile.account_id){draft={country:activeCountry,account:profile.account_id,revision:data.navigationSettings?.revision||0,config:config()};dirty=false;}return draft;}
const previousContent=renderContent;
renderContent=function(){if(view==='navigation'&&profile&&activeCountry){if(profile.role!=='admin'){view='board';return previousContent();}return draw();}return previousContent();};
function fields(values,placeholder,attrs){return ['zh','en','es','vi'].map(l=>`<label>${l.toUpperCase()}<input class="select" maxlength="120" value="${esc(values?.[l]||'')}" placeholder="${esc(placeholder?.[l]||'')}" ${attrs} data-language="${l}"></label>`).join('');}
function draw(){const state=draftForCountry(),c=state.config;$('.page-title h1').innerHTML=txt('navigation');$('#content').innerHTML=`<p class="notice">${txt('navHelp')}</p><div class="nav-editor">${c.sections.map(s=>`<section class="nav-editor-group"><h2>● ${esc(multilingual(label(s.label,s.id)))}</h2><div class="nav-name-fields">${fields(s.label,translations[s.id],`data-section-label="${esc(s.id)}"`)}</div><div class="nav-editor-list">${c.items.filter(i=>i.section===s.id).map(i=>`<article class="nav-editor-row" data-menu-row="${i.key}"><strong>${txt(i.key)}</strong><div class="nav-name-fields">${fields(i.label,translations[i.key],`data-item-label="${i.key}"`)}</div><div class="nav-editor-actions"><label><input type="checkbox" data-visible="${i.key}" ${i.visible?'checked':''} ${i.key==='navigation'?'disabled':''}>${txt('navVisible')}</label><label>${txt('navGroup')}<select class="select" data-menu-group="${i.key}">${c.sections.map(g=>`<option value="${esc(g.id)}" ${g.id===s.id?'selected':''}>${esc(multilingual(label(g.label,g.id)))}</option>`).join('')}</select></label><button class="btn secondary" data-move="${i.key}" data-direction="-1" ${c.items.filter(x=>x.section===s.id)[0]===i?'disabled':''}>↑ ${txt('navUp')}</button><button class="btn secondary" data-move="${i.key}" data-direction="1" ${c.items.filter(x=>x.section===s.id).at(-1)===i?'disabled':''}>↓ ${txt('navDown')}</button></div></article>`).join('')}</div></section>`).join('')}</div><div class="filter-row"><label>${txt('navGroupName')}<input id="navGroupName" class="select" maxlength="120"></label><button class="btn secondary" id="navAddGroup" ${c.sections.length>=8?'disabled':''}>${txt('navAddGroup')}</button></div><div class="filter-row"><button class="btn primary" id="navSave" ${saving?'disabled':''}>${txt('save')}</button><button class="btn secondary" id="navReset">${txt('navReset')}</button><button class="btn secondary" id="navReload">${txt('navReload')}</button></div><p id="navMessage" role="status"></p>`;
 $$('[data-item-label],[data-section-label]').forEach(el=>el.oninput=()=>{const row=el.dataset.itemLabel?c.items.find(i=>i.key===el.dataset.itemLabel):c.sections.find(s=>s.id===el.dataset.sectionLabel);row.label[el.dataset.language]=el.value.trim().replace(/^[●▶]\s*/, '');dirty=true;});
 $$('[data-visible]').forEach(el=>el.onchange=()=>{c.items.find(i=>i.key===el.dataset.visible).visible=el.checked;dirty=true;});
 $$('[data-menu-group]').forEach(el=>el.onchange=()=>{c.items.find(i=>i.key===el.dataset.menuGroup).section=el.value;dirty=true;draw();});
 $$('[data-move]').forEach(el=>el.onclick=()=>{const i=c.items.find(x=>x.key===el.dataset.move),list=c.items.filter(x=>x.section===i.section),other=list[list.indexOf(i)+Number(el.dataset.direction)];if(!other)return;const a=c.items.indexOf(i),b=c.items.indexOf(other);[c.items[a],c.items[b]]=[c.items[b],c.items[a]];dirty=true;draw();});
 $('#navAddGroup').onclick=()=>{const name=$('#navGroupName').value.trim();if(!name||/[<>]/.test(name)||c.sections.length>=8)return;c.sections.push({id:'custom_'+Date.now().toString(36),label:{zh:name}});dirty=true;draw();};
 $('#navReset').onclick=()=>{if(!confirm(t('navResetConfirm')))return;state.config=original();dirty=true;draw();};
 $('#navReload').onclick=async()=>{if(dirty&&!confirm(t('navDiscard')))return;try{const r=await api({action:'workspace'});data=r;draft=null;dirty=false;render();}catch{$('#navMessage').textContent=t('error');}};
 $('#navSave').onclick=async()=>{if(saving)return;saving=true;const ctry=activeCountry,account=profile.account_id;for(const el of $('#content').querySelectorAll('input,select,button'))el.disabled=true;try{const r=await api({action:'navigation_save',revision:state.revision,config:state.config});if(ctry!==activeCountry||account!==profile?.account_id)return;data.navigationSettings=r.navigationSettings;draft=null;dirty=false;render();$('#navMessage').textContent=t('saved');}catch(e){if(ctry===activeCountry&&view==='navigation'){$('#navMessage').textContent=t(e.message==='record_changed'?'navConflict':'navInvalid');}}finally{saving=false;if(view==='navigation'&&ctry===activeCountry){$('#navSave').disabled=false;for(const el of $('#content').querySelectorAll('input,select,button'))el.disabled=false;$('#content [data-visible="navigation"]').disabled=true;}}};
}
let sidebarScope='',sidebarView='';
function foldState(){const key='inspection_menu_folds:'+activeCountry+':'+profile.account_id;let values={};try{const saved=JSON.parse(localStorage.getItem(key)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))values=saved;}catch{}return {values,save(){try{localStorage.setItem(key,JSON.stringify(values));}catch{}}};}
const oldRender=render;
render=function(){if(view==='navigation'&&profile?.role!=='admin')view='board';oldRender();if(profile&&activeCountry){
 const nav=$('.side'),buttons=new Map([...nav.querySelectorAll('[data-view]')].map(b=>[b.dataset.view,b]));
 if(profile.role==='admin'){const b=document.createElement('button');b.className='nav'+(view==='navigation'?' active':'');b.dataset.view='navigation';b.onclick=()=>{view='navigation';render();};buttons.set('navigation',b);}
 const c=config(),scope=activeCountry+':'+profile.account_id,reveal=sidebarScope!==scope||sidebarView!==view,folds=foldState();sidebarScope=scope;sidebarView=view;nav.replaceChildren();for(const s of c.sections){const rows=c.items.filter(i=>i.section===s.id&&buttons.has(i.key)&&(i.visible||i.key==='navigation'));if(!rows.length)continue;const current=rows.some(i=>i.key===view),section=document.createElement('details');section.className='nav-section';section.dataset.section=s.id;section.open=reveal&&current?true:typeof folds.values[s.id]==='boolean'?folds.values[s.id]:current||s.id==='field';const title=document.createElement('summary');title.className='side-label nav-section-title';const name=document.createElement('span');name.textContent='● '+multilingual(label(s.label,s.id));const arrow=document.createElement('span');arrow.className='nav-section-arrow';arrow.setAttribute('aria-hidden','true');arrow.textContent='›';title.append(name,arrow);section.append(title);const items=document.createElement('div');items.className='nav-section-items';for(const i of rows){const b=buttons.get(i.key);b.innerHTML=`<span class="menu-symbol" aria-hidden="true">▶</span><span class="menu-text">${esc(multilingual(label(i.label,i.key)))}</span>`;if(i.key===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');const action=b.onclick;b.onclick=e=>{if(saving)return;if(view==='navigation'&&dirty&&i.key!=='navigation'){if(!confirm(t('navDiscard')))return;draft=null;dirty=false;}if(i.key==='items')kind='daily';action?.call(b,e);};items.append(b);}section.append(items);nav.append(section);section.addEventListener('toggle',()=>{if(!section.isConnected||sidebarScope!==scope)return;folds.values[s.id]=section.open;folds.save();});}
 }banner();};
 // Compare all languages, item order and reference photo IDs; never alter assignments/history.
 function stable(v){if(Array.isArray(v))return v.map(stable);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).sort().map(k=>[k,stable(v[k])]));return v;}
 const fullList=formList;formList=function(){const list=fullList();if(view!=='items'||kind!=='daily'||showDuplicates)return list;const seen=new Set();return list.filter(f=>{if(f.department!=='螺帽成型組')return true;const key=JSON.stringify([f.department,f.equipment_name,stable(f.items)]);if(seen.has(key))return false;seen.add(key);return true;});};
 const previousForms=renderForms;renderForms=function(){previousForms();if(view!=='items')return;$('#kind')?.remove();const count=fullList().length-formList().length;const note=document.createElement('div');note.className='notice';note.innerHTML=`${txt('duplicatesHint')} <label><input id="showDuplicateForms" type="checkbox" ${showDuplicates?'checked':''}>${txt('showDuplicates')}${count?` (${count})`:''}</label>`;$('#content').prepend(note);$('#showDuplicateForms').onchange=e=>{showDuplicates=e.target.checked;renderContent();};};
 // Preserve legacy crane matching while displaying the current terminology.
 const escaped=esc;esc=function(v){return escaped(typeof v==='string'?v.replace(/天車/g,'固定式起重機'):v);};
 function banner(){let el=$('#connectivityBanner');if(!el){el=document.createElement('div');el.id='connectivityBanner';el.setAttribute('role','alert');el.setAttribute('aria-live','polite');$('#app').prepend(el);}el.hidden=navigator.onLine&&!networkFailed;el.textContent=t(!navigator.onLine?'offlineHint':'networkProblem');}
 const oldApi=api;api=async function(payload){try{const r=await oldApi(payload);networkFailed=false;banner();return r;}catch(e){if(!navigator.onLine||e instanceof TypeError||/failed to fetch|networkerror|network request/i.test(e.message)){networkFailed=true;banner();}throw e;}};
 window.addEventListener('offline',banner);window.addEventListener('online',()=>{networkFailed=false;banner();toast('networkBack');});
 window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
 render();
})();
